-- Description: Session 8A — Agartala Delivery Zone, PostGIS Point-in-Polygon Serviceability,
--              Unified Commerce Validation & Address Map Verification
-- =============================================================================

-- 1. Ensure PostGIS extension is enabled
CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA extensions;

-- 2. Create public.delivery_zones table
CREATE TABLE IF NOT EXISTS public.delivery_zones (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  city text NOT NULL,
  state text NOT NULL,
  country text NOT NULL DEFAULT 'India',
  is_active boolean NOT NULL DEFAULT true,
  boundary extensions.geometry(MultiPolygon, 4326) NOT NULL,
  delivery_fee numeric(10,2) NOT NULL DEFAULT 30.00,
  free_delivery_threshold numeric(10,2) NOT NULL DEFAULT 499.00,
  minimum_order_amount numeric(10,2) NOT NULL DEFAULT 0.00,
  source_name text NOT NULL,
  source_reference text NOT NULL,
  boundary_version text DEFAULT '2024-10-23',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Spatial index for sub-millisecond point-in-polygon queries
CREATE INDEX IF NOT EXISTS idx_delivery_zones_boundary ON public.delivery_zones USING GIST (boundary);

-- Row Level Security
ALTER TABLE public.delivery_zones ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Active delivery zones are readable by everyone" ON public.delivery_zones;
CREATE POLICY "Active delivery zones are readable by everyone"
  ON public.delivery_zones
  FOR SELECT
  USING (is_active = true);

-- Protect delivery zone configuration from unauthorized client mutations
REVOKE INSERT, UPDATE, DELETE ON public.delivery_zones FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.delivery_zones TO anon, authenticated, service_role;

-- 3. Seed active Agartala City delivery zone
DELETE FROM public.delivery_zones WHERE code = 'agartala_city';

