-- 4. Server Point-in-Polygon Serviceability RPC
CREATE OR REPLACE FUNCTION public.rpc_check_delivery_serviceability(
  p_latitude double precision,
  p_longitude double precision
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_point extensions.geometry;
  v_zone record;
BEGIN
  -- Validate coordinates presence
  IF p_latitude IS NULL OR p_longitude IS NULL THEN
    RETURN jsonb_build_object(
      'serviceable', false,
      'reason_code', 'LOCATION_REQUIRED',
      'message', 'Latitude and longitude coordinates are required.'
    );
  END IF;

  -- Validate coordinate geographical ranges
  IF p_latitude < -90.0 OR p_latitude > 90.0 OR p_longitude < -180.0 OR p_longitude > 180.0 THEN
    RETURN jsonb_build_object(
      'serviceable', false,
      'reason_code', 'INVALID_COORDINATES',
      'message', 'Coordinates are outside valid geographical bounds.'
    );
  END IF;

  -- Construct PostGIS Point (X = Longitude, Y = Latitude, SRID = 4326)
  v_point := extensions.ST_SetSRID(extensions.ST_MakePoint(p_longitude, p_latitude), 4326);

  -- Check active delivery zone using ST_Covers (includes polygon boundary edge)
  SELECT 
    id, code, name, city, state, delivery_fee, free_delivery_threshold, minimum_order_amount
  INTO v_zone
  FROM public.delivery_zones
  WHERE is_active = true
    AND extensions.ST_Covers(boundary, v_point)
  LIMIT 1;

  IF v_zone.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'serviceable', true,
      'zone_id', v_zone.id,
      'zone_code', v_zone.code,
      'zone_name', v_zone.name,
      'delivery_fee', v_zone.delivery_fee,
      'free_delivery_threshold', v_zone.free_delivery_threshold,
      'minimum_order_amount', v_zone.minimum_order_amount,
      'reason_code', 'SERVICEABLE',
      'message', 'FreshMarket delivers to this location in Agartala.'
    );
  END IF;

  -- Check if coordinates fall within an inactive delivery zone
  IF EXISTS (
    SELECT 1 FROM public.delivery_zones 
    WHERE is_active = false AND extensions.ST_Covers(boundary, v_point)
  ) THEN
    RETURN jsonb_build_object(
      'serviceable', false,
      'reason_code', 'DELIVERY_ZONE_DISABLED',
      'message', 'Delivery is temporarily paused in this zone.'
    );
  END IF;

  RETURN jsonb_build_object(
    'serviceable', false,
    'reason_code', 'OUTSIDE_DELIVERY_ZONE',
    'message', 'FreshMarket currently delivers only within Agartala city.'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_check_delivery_serviceability(double precision, double precision) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_check_delivery_serviceability(double precision, double precision) TO anon, authenticated, service_role;

